const app=document.getElementById("app"), modalRoot=document.getElementById("modal-root"), toastRoot=document.getElementById("toast-root");
const state={token:localStorage.getItem("lc_token"),user:JSON.parse(localStorage.getItem("lc_user")||"null"),page:"overview",cache:{},sidebar:false};
const icons={overview:"⌂",requests:"🩸",invitations:"✉",availability:"◉",notifications:"♧",profile:"◎",outreach:"➤",staff:"♙",reports:"▥",subscription:"◇",verification:"✓",users:"♧",plans:"▤",audit:"≋",settings:"⚙",help:"?",privacy:"⌑"};
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
async function apiUpload(path,formData){const headers={};if(state.token)headers.Authorization="Bearer "+state.token;let res;try{res=await fetch(path,{method:"POST",headers,body:formData})}catch(error){if(error instanceof TypeError)throw new Error("LifeConnect server is not reachable. Start the website server, then try again.");throw error}let data={};try{data=await res.json()}catch{}if(!res.ok)throw new Error(data.detail||"Something went wrong");return data}
async function api(path,opts={}){
  const headers={"Content-Type":"application/json",...(opts.headers||{})};
  if(state.token)headers.Authorization="Bearer "+state.token;
  let res;
  try{res=await fetch(path,{...opts,headers})}
  catch(error){
    if(error instanceof TypeError)throw new Error("LifeConnect server is not reachable. Start the website server, then try again.");
    throw error;
  }
  let data={};
  try{data=await res.json()}catch{}
  if(!res.ok)throw new Error(data.detail||"Something went wrong");
  return data;
}
function toast(msg,type=""){const el=document.createElement("div");el.className="toast "+type;el.textContent=msg;toastRoot.appendChild(el);setTimeout(()=>el.remove(),3600)}
function showModal(title,body,actions=""){modalRoot.innerHTML=`<div class="modal-backdrop" data-close><section class="modal" role="dialog" aria-modal="true"><header class="modal-head"><h3>${title}</h3><button class="close" data-close>×</button></header><div class="modal-body">${body}</div>${actions?`<footer class="modal-foot">${actions}</footer>`:""}</section></div>`;modalRoot.querySelectorAll("[data-close]").forEach(x=>x.addEventListener("click",e=>{if(e.target===x||x.classList.contains("close"))modalRoot.innerHTML=""}));}
function closeModal(){modalRoot.innerHTML=""}
function status(s){return `<span class="status ${String(s).toLowerCase().replace(/[^a-z]+/g,"-")}">${esc(s)}</span>`}
function brand(){return `<div class="brand"><img class="brand-logo" src="/static/lifeconnect-logo-small.png" alt="LifeConnect AI"></div>`}
function avatarMarkup(user,className="avatar"){const initials=(user?.name||"U").split(" ").map(part=>part[0]).slice(0,2).join("");return user?.profile_image_url?`<img class="${className} avatar-image" src="${esc(user.profile_image_url)}" alt="${esc(user.name||"User")} profile photo">`:`<div class="${className}" aria-label="${esc(user?.name||"User")}">${esc(initials)}</div>`}
function setButtonLoading(button,label){if(!button)return null;const previous={html:button.innerHTML,disabled:button.disabled};button.disabled=true;button.setAttribute("aria-busy","true");button.innerHTML=`<span class="button-spinner" aria-hidden="true"></span>${esc(label)}`;return previous}
function restoreButton(button,previous){if(!button||!previous)return;button.innerHTML=previous.html;button.disabled=previous.disabled;button.removeAttribute("aria-busy")}
function showInfo(t,txt){showModal(t,`<p>${esc(txt)}</p><div class="notice">LifeConnect AI is a coordination tool. Clinical decisions remain with qualified healthcare professionals.</div>`)}
function saveSession(d){state.token=d.token;state.user=d.user;localStorage.setItem("lc_token",d.token);localStorage.setItem("lc_user",JSON.stringify(d.user))}
function logout(){state.token=null;state.user=null;localStorage.removeItem("lc_token");localStorage.removeItem("lc_user");publicSite()}
const menus={donor:[["WORKSPACE",["overview","Overview"],["invitations","Invitations"],["availability","Availability"],["notifications","Notifications"]],["ACCOUNT",["profile","My profile"],["privacy","Privacy & settings"],["help","Help & support"]]],facility:[["WORKSPACE",["overview","Overview"],["requests","Blood requests"],["ai","AI assistant"],["outreach","Donor outreach"],["reports","Reports & analytics"],["notifications","Notifications"]],["FACILITY",["staff","Staff & roles"],["subscription","Subscription"],["profile","Facility profile"],["help","Help & support"]]],admin:[["PLATFORM",["overview","Platform overview"],["verification","Facility verification"],["users","User management"],["plans","Plans & billing"],["notifications","Notification monitoring"],["audit","Audit & security logs"],["ai","AI assistant"],["settings","AI configuration"]],["SUPPORT",["help","Help & support"]]]};
async function renderApp(){try{state.user=await api("/api/me");localStorage.setItem("lc_user",JSON.stringify(state.user));}catch(e){logout();return}const role=state.user.role;const menu=menus[role]||menus.donor;app.innerHTML=`<div class="app-shell"><aside class="sidebar ${state.sidebar?"open":""}" id="sidebar">${brand()}${menu.map(group=>`<div class="side-label">${group[0]}</div>${group.slice(1).map(([id,label])=>`<button class="side-link ${state.page===id?"active":""}" onclick="go('${id}')"><span class="ico">${icons[id]||"•"}</span>${label}</button>`).join("")}`).join("")}<div class="sidebar-bottom"><button class="side-link" onclick="showInfo('Safety & responsibility','LifeConnect coordinates communications only. Qualified facility professionals own screening, testing, compatibility and transfusion decisions.')">ⓘ Safety guidance</button><button class="side-link" onclick="logout()">↪ Sign out</button></div></aside><main class="main-area"><header class="app-top"><div style="display:flex;align-items:center;gap:12px"><button class="btn outline btn-sm mobile-menu" onclick="toggleSidebar()">☰</button><div><b style="font:700 14px Manrope;color:var(--navy)">LifeConnect workspace</b><div class="small muted">${role==="admin"?"Platform administration":role==="facility"?"Institution portal":"Donor portal"}</div></div></div><div class="top-user"><button class="btn ghost btn-sm notification-trigger" onclick="openNotificationPopup()" aria-label="Open notifications"><span aria-hidden="true">&#128276;</span><span id="notification-badge" class="notification-badge" hidden></span></button>${avatarMarkup(state.user)}<div><b style="font-size:12px">${esc(state.user.name)}</b><div class="small muted">${esc(roleLabel(role))}</div></div></div></header><div class="content" id="page-content"><div class="empty">Loading workspace…</div></div></main></div>`;await go(state.page);refreshNotificationBadge()}
function roleLabel(r){return r==="admin"?"Platform administrator":r==="facility"?"Facility staff":"Volunteer donor"}
function toggleSidebar(){state.sidebar=!state.sidebar;document.getElementById("sidebar").classList.toggle("open",state.sidebar)}
async function go(page){state.page=page;document.querySelectorAll(".side-link").forEach(x=>x.classList.toggle("active",x.getAttribute("onclick")===`go('${page}')`));document.getElementById("sidebar")?.classList.remove("open");state.sidebar=false;const c=document.getElementById("page-content");if(!c)return;c.innerHTML='<div class="empty">Loading…</div>';try{const fn=pages[page]||pages.overview;c.innerHTML=await fn()}catch(e){c.innerHTML=`<div class="panel"><h3>Unable to load this page</h3><p>${esc(e.message)}</p></div>`}}
function head(title,desc,action=""){return `<div class="page-head"><div><div class="eyebrow">${roleLabel(state.user.role)}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function statCards(stats){return `<div class="stats">${stats.map(s=>`<div class="stat-card"><div class="stat-top"><span>${esc(s.label)}</span><span class="stat-icon">${icons[s.icon]||"✦"}</span></div><div class="stat-value">${esc(s.value)}</div><div class="stat-foot">Live demo workspace</div></div>`).join("")}</div>`}
function activityPanel(rows){return `<div class="panel"><div class="panel-head"><h3>Recent activity</h3><span class="small muted">Latest updates</span></div>${rows.length?rows.map(n=>`<div class="activity"><div class="activity-dot"></div><div><strong>${esc(n.title)}</strong><p>${esc(n.message)}</p><span class="small muted">${new Date(n.time).toLocaleString()}</span></div></div>`).join(""):'<div class="empty">No activity yet.</div>'}</div>`}
async function overview(){const d=await api("/api/dashboard");let intro=state.user.role==="donor"?"Manage your participation, preferences and invitations in one place.":state.user.role==="facility"?"Coordinate facility requests, review donor responses and track operational activity.":"Monitor platform activity, institution verification and operational trust controls.";let quick=state.user.role==="donor"?`<button class="btn teal" onclick="go('invitations')">Review invitations</button><button class="btn outline" onclick="go('availability')">Update availability</button>`:state.user.role==="facility"?`<button class="btn teal" onclick="newRequest()">＋ Create request</button><button class="btn outline" onclick="go('outreach')">Review outreach</button>`:`<button class="btn teal" onclick="go('verification')">Review facilities</button><button class="btn outline" onclick="go('audit')">View audit log</button>`;return head("Good to see you, "+esc(state.user.name.split(" ")[0]),intro,quick)+`<div class="workspace-banner"><div><div class="eyebrow">Your LifeConnect workspace</div><h2>Better coordination starts with a clear view.</h2><p>Keep preferences, requests and follow-up activity in one place.</p></div><img src="/static/lifeconnect-hero.svg" alt="Volunteer donor and healthcare worker at a community clinic"></div>`+statCards(d.stats)+`<div class="two-col"><div>${activityPanel(d.activity)}${state.user.role==="facility"?await requestPanel():state.user.role==="admin"?await verificationSummary():""}</div><div><div class="panel"><div class="panel-head"><h3>Quick actions</h3></div><div class="profile-row"><div class="profile-icon">♙</div><div><b>Account & preferences</b><p class="small">Keep your information and choices current.</p></div></div><div class="profile-row"><div class="profile-icon">♧</div><div><b>Notifications</b><p class="small">Review updates and communication history.</p></div></div><div class="profile-row"><div class="profile-icon">ⓘ</div><div><b>Safety first</b><p class="small">Clinical decisions remain with qualified staff.</p></div></div></div><div class="notice warn">This is a synthetic demonstration environment.</div></div></div>`}
async function requestPanel(){const rs=await api("/api/requests");return `<div class="panel"><div class="panel-head"><h3>Recent blood requests</h3><button class="btn ghost btn-sm" onclick="go('requests')">View all →</button></div>${tableRequests(rs.slice(0,4))}</div>`}
async function verificationSummary(){const fs=await api("/api/admin/facilities");return `<div class="panel"><div class="panel-head"><h3>Facility review queue</h3><button class="btn ghost btn-sm" onclick="go('verification')">View queue →</button></div><p>${fs.filter(f=>f.verification==="pending").length} facilities awaiting review.</p></div>`}
function tableRequests(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Reference</th><th>Group</th><th>Urgency</th><th>Status</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.reference)}</b><div class="small muted">${esc(r.facility||"")}</div></td><td>${esc(r.blood_group)}</td><td>${status(r.urgency)}</td><td>${status(r.status)}</td></tr>`).join("")}</tbody></table></div>`:'<div class="empty">No requests yet.</div>'}
async function requestsPage(){const rs=await api("/api/requests");return head("Blood requests","Create, review and track requests created by your facility.",`<button class="btn teal" onclick="newRequest()">＋ New request</button>`)+`<div class="panel"><div class="toolbar"><input class="search" id="req-search" placeholder="Search reference, location…" oninput="filterTable('req-search','requests-table')"><select class="search" id="req-filter" onchange="filterStatus('req-filter','requests-table')"><option value="">All statuses</option>${["draft","submitted","verified/approved internally","outreach active","fulfilled","cancelled","expired"].map(s=>`<option>${s}</option>`).join("")}</select></div><div id="requests-table">${tableRequestsDetailed(rs)}</div></div>`}
function tableRequestsDetailed(rs){return rs.length?`<div class="table-wrap"><table><thead><tr><th>Request</th><th>Group / units</th><th>Urgency</th><th>Location</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rs.map(r=>`<tr data-status="${esc(r.status)}" data-search="${esc((r.reference+r.location+r.facility).toLowerCase())}"><td><b>${esc(r.reference)}</b><div class="small muted">${esc(r.facility)}</div></td><td>${esc(r.blood_group)} · ${r.quantity}</td><td>${status(r.urgency)}</td><td>${esc(r.location)}</td><td>${status(r.status)}</td><td><button class="btn outline btn-sm" onclick="requestDetails(${r.id})">Details</button></td></tr>`).join("")}</tbody></table></div>`:'<div class="empty">No blood requests found.</div>'}
function filterTable(input,table){const q=document.getElementById(input).value.toLowerCase();document.querySelectorAll(`#${table} tbody tr`).forEach(r=>r.style.display=r.dataset.search?.includes(q)?"":"none")}
function filterStatus(input,table){const q=document.getElementById(input).value;document.querySelectorAll(`#${table} tbody tr`).forEach(r=>r.style.display=!q||r.dataset.status===q?"":"none")}
function newRequest(draft=null){
  const values=draft||{};
  const selected=(field,value)=>values[field]===value?"selected":"";
  const verified=state.user.facility?.verification==="approved";
  const guidance=verified
    ?"Submitting this request immediately invites active, available donors who opted in. Email alerts are sent when SMTP is configured. Do not include patient names or private medical details."
    :"Facility verification is pending. You can save this as a draft; no donor notifications are sent until the facility is approved.";
  showModal("Create a blood request",`<div class="notice warn">${guidance}</div><form id="new-req" style="margin-top:18px"><div class="form-grid"><div class="field"><label>Blood group / category as supplied by staff</label><select name="blood_group" required><option value="">Select</option>${["A+","A-","B+","B-","AB+","AB-","O+","O-","Not specified"].map(x=>`<option ${selected("blood_group",x)}>${x}</option>`).join("")}</select></div><div class="field"><label>Quantity / units</label><input name="quantity" type="number" min="1" max="100" value="${esc(values.quantity||1)}" required></div><div class="field"><label>Urgency label</label><select name="urgency"><option ${selected("urgency","standard")}>standard</option><option ${selected("urgency","urgent")}>urgent</option><option ${selected("urgency","critical")}>critical</option></select></div><div class="field"><label>Request expiry</label><input name="expires_at" type="date" value="${esc(values.expires_at||"")}"></div></div><div class="field"><label>Facility location</label><input name="location" required placeholder="Facility address / area" value="${esc(values.location||state.user.facility?.address||"")}"></div><div class="field"><label>Contact person / role</label><input name="contact_person" placeholder="Duty blood bank officer" value="${esc(values.contact_person||"")}"></div><div class="field"><label>Operational notes (minimum necessary)</label><textarea name="notes" placeholder="No patient names or unrestricted medical notes">${esc(values.notes||"")}</textarea></div></form>`,`<button class="btn outline" data-close>Cancel</button><button class="btn primary" onclick="submitRequest()">${verified?"Submit request & notify donors":"Save draft"}</button>`);
}
async function submitRequest(){const f=document.getElementById("new-req");if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));d.quantity=Number(d.quantity);const button=modalRoot.querySelector(".modal-foot .btn.primary"),previous=setButtonLoading(button,"Submitting...");try{const r=await api("/api/requests",{method:"POST",body:JSON.stringify(d)});closeModal();toast(r.message||("Request "+r.reference+" created"),r.status==="draft"?"":"success");go("requests")}catch(e){toast(e.message,"error");restoreButton(button,previous)}}
async function requestDetails(id){const all=await api("/api/requests"),r=all.find(x=>x.id===id);if(!r)return;const isFacility=state.user.role==="facility";let actions=isFacility?`<button class="btn outline" onclick="showResponses(${id})">Donor responses</button><button class="btn teal" onclick="previewOutreach(${id})">Preview outreach</button>`:"";showModal(`Request ${r.reference}`,`<div class="profile-row"><div class="profile-icon">🩸</div><div><b>${esc(r.blood_group)} · ${r.quantity} units</b><p class="small">${esc(r.facility)} · ${esc(r.location)}</p></div></div><p><b>Urgency:</b> ${status(r.urgency)} &nbsp; <b>Status:</b> ${status(r.status)}</p><p><b>Contact:</b> ${esc(r.contact_person||"Not supplied")}</p><p><b>Notes:</b> ${esc(r.notes||"None")}</p><div class="notice">Facility staff remain responsible for request approval, screening, testing and all clinical decisions.</div>`,`${actions}<button class="btn outline" data-close>Close</button>`)}
async function previewOutreach(id){try{const d=await api("/api/outreach/preview/"+id);showModal("Review outreach suggestions",`<div class="notice warn">${esc(d.notice)}</div><p><b>${d.candidates.length}</b> opted-in donor profile(s) meet the non-clinical preference filters.</p>${d.candidates.length?`<div class="table-wrap"><table><thead><tr><th>Donor</th><th>Location</th><th>Language</th><th>Basis</th></tr></thead><tbody>${d.candidates.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.location)}</td><td>${esc(x.language)}</td><td>${esc(x.selection_basis)}</td></tr>`).join("")}</tbody></table></div>`:'<div class="empty">No opted-in available donors matched this demo filter.</div>'}<p class="small muted">Submitting the request already notified opted-in donors. Approve this additional batch to invite any matching donors who have not received it. No blood compatibility or medical eligibility is inferred.</p>`,`<button class="btn outline" data-close>Cancel</button><button class="btn teal" onclick="approveOutreach(${id})">Invite matched donors</button>`)}catch(e){toast(e.message,"error")}}
async function approveOutreach(id){if(!confirm("Send invitations to active, available donors who opted in and have not already received this request?"))return;try{const d=await api("/api/outreach/approve/"+id,{method:"POST"});closeModal();toast(`${d.invitations_created} demo invitation(s) created`);go("requests")}catch(e){toast(e.message,"error")}}
async function showResponses(id){try{const rows=await api(`/api/requests/${id}/responses`);showModal("Donor responses",rows.length?`<div class="table-wrap"><table><thead><tr><th>Donor</th><th>Response</th><th>Delivery</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.donor)}</td><td>${status(x.response)}</td><td>${status(x.delivery)}</td></tr>`).join("")}</tbody></table></div>`:'<div class="empty">No responses recorded yet.</div>')}catch(e){toast(e.message,"error")}}
async function invitationsPage(){const rows=await api("/api/invitations");return head("Your invitations","Review requests from participating facilities. Your response means willingness to be contacted only.")+`<div class="notice warn" style="margin-bottom:16px">Accepting an invitation is not a medical eligibility decision. The facility will guide you through its own screening process.</div><div class="grid3">${rows.map(r=>`<div class="feature"><div class="eyebrow">${esc(r.reference)} · ${status(r.response)}</div><h3 style="margin-top:12px">${esc(r.facility)}</h3><p><b>${esc(r.blood_group)}</b> · ${esc(r.location)}</p><p>Urgency: ${esc(r.urgency)}</p><div class="small muted">Facility verification: ${esc(r.verification)}</div><div style="display:flex;gap:7px;flex-wrap:wrap;margin-top:15px">${r.response==="pending"?`<button class="btn teal btn-sm" onclick="respondInvite(${r.id},'accepted')">I'm interested</button><button class="btn outline btn-sm" onclick="respondInvite(${r.id},'contact me')">Contact me</button><button class="btn danger btn-sm" onclick="respondInvite(${r.id},'declined')">Decline</button>`:'<span class="small muted">Response recorded</span>'}</div></div>`).join("")||'<div class="feature empty">No invitations yet. You will see invitations here when a verified facility sends them.</div>'}</div>`}
async function respondInvite(id,response){try{await api(`/api/invitations/${id}/respond`,{method:"POST",body:JSON.stringify({response_status:response})});toast("Your response has been recorded");go("invitations")}catch(e){toast(e.message,"error")}}
async function availabilityPage(){const p=state.user.profile||{};return head("Availability & preferences","You control when and how participating facilities can contact you.")+`<div class="panel" style="max-width:760px"><form id="prefs"><div class="field"><label>Availability</label><select name="availability_status"><option value="available" ${p.availability==="available"?"selected":""}>Available for invitations</option><option value="temporarily unavailable" ${p.availability==="temporarily unavailable"?"selected":""}>Temporarily unavailable</option><option value="paused" ${p.availability==="paused"?"selected":""}>Paused</option></select></div><div class="form-grid"><div class="field"><label>Broad location</label><input value="${esc(p.location||"Jos, Plateau State")}" disabled></div><div class="field"><label>Outreach radius (km)</label><input name="radius_km" type="number" min="1" max="250" value="${p.radius_km||25}"></div></div><div class="field"><label>Preferred language</label><select name="preferred_language">${["English","Hausa","Yoruba","Igbo"].map(x=>`<option ${p.language===x?"selected":""}>${x}</option>`).join("")}</select></div><h3 style="font-size:15px;margin:20px 0 8px">Notification channels</h3>${["email_enabled","sms_enabled","inapp_enabled"].map((x,i)=>`<label class="checkline"><input type="checkbox" name="${x}" ${p[x]?"checked":""}><span>${["Email","Optional SMS","In-app"][i]} notifications</span></label>`).join("")}<label class="checkline"><input type="checkbox" name="consent_status" ${p.consent?"checked":""}><span>I consent to receive donor invitations through selected channels. I can withdraw consent or pause participation at any time.</span></label><button class="btn primary" type="submit">Save preferences</button></form></div>`}
async function savePrefs(e){e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f)),button=f.querySelector('[type="submit"]'),previous=setButtonLoading(button,"Saving...");for(const x of ["email_enabled","sms_enabled","inapp_enabled","consent_status"])d[x]=f.elements[x].checked;d.radius_km=Number(d.radius_km);try{await api("/api/donor/preferences",{method:"PATCH",body:JSON.stringify(d)});toast("Preferences updated");state.user=await api("/api/me");go("availability")}catch(e){toast(e.message,"error");restoreButton(button,previous)}}
async function openNotificationPopup(){try{const rows=await api("/api/notifications");refreshNotificationBadge(rows);const body=rows.length?rows.slice(0,8).map(n=>`<div class="notification-item"><b>${esc(n.title)}</b><p>${esc(n.message)}</p><span class="small muted">${new Date(n.time).toLocaleString()}</span></div>`).join(""):'<div class="empty">No notifications yet.</div>';showModal("Notifications",`<div class="notification-list">${body}</div>`,`<button class="btn outline" data-close>Close</button><button class="btn primary" onclick="closeModal();go('notifications')">Open notification centre</button>`)}catch(error){toast(error.message,"error")}}
function refreshNotificationBadge(rows=null){if(!rows){api("/api/notifications").then(refreshNotificationBadge).catch(()=>{});return}const badge=document.getElementById("notification-badge");if(!badge)return;badge.textContent=rows.length>9?"9+":String(rows.length);badge.hidden=rows.length===0}
async function sendAnnouncement(event){event.preventDefault();const form=event.target;if(!form.reportValidity())return;const submit=form.querySelector('[type="submit"]'),values=Object.fromEntries(new FormData(form));const previous=setButtonLoading(submit,"Sending?");try{const result=await api("/api/notifications/broadcast",{method:"POST",body:JSON.stringify(values)});toast(`Announcement sent to ${result.recipients} active users.`,"success");refreshNotificationBadge();go("notifications")}catch(error){toast(error.message,"error");restoreButton(submit,previous)}}
async function notificationsPage(){const rows=await api("/api/notifications"),canBroadcast=["facility","admin"].includes(state.user.role);const composer=canBroadcast?`<form id="announcement-form" class="panel announcement-form"><div class="panel-head"><div><h3>Share an announcement</h3><span class="small muted">Visible to all active LifeConnect users</span></div></div><div class="field"><label for="announcement-title">Title</label><input id="announcement-title" name="title" maxlength="120" required placeholder="Announcement title"></div><div class="field"><label for="announcement-message">Message</label><textarea id="announcement-message" name="message" maxlength="2000" required placeholder="Write a clear service update or announcement"></textarea></div><button class="btn primary" type="submit">Send to everyone</button></form>`:"";return head("Notifications","Updates about invitations, request activity, verification and account events.")+composer+`<div class="panel"><div class="panel-head"><h3>Recent notifications</h3><span class="small muted">Latest ${rows.length}</span></div>${rows.length?rows.map(n=>`<div class="activity"><div class="activity-dot"></div><div><strong>${esc(n.title)}</strong><p>${esc(n.message)}</p><span class="small muted">${new Date(n.time).toLocaleString()} | ${esc(n.category)}</span></div></div>`).join(""):'<div class="empty">You are all caught up.</div>'}</div>`}
async function profilePage(){
 const u=state.user,p=u.profile||{},f=u.facility||{},donor=u.role==="donor",facility=u.role==="facility";
 return head(facility?"Facility profile":"My profile","Update your account details and profile photo.")+`<div class="panel profile-editor"><div class="profile-photo-row">${avatarMarkup(u,"profile-avatar")}<div><h3>${esc(u.name)}</h3><p>${esc(u.email)} &middot; ${esc(roleLabel(u.role))}</p><form id="avatar-form"><label class="btn outline btn-sm" for="profile-image">Choose profile photo</label><input id="profile-image" type="file" accept="image/jpeg,image/png,image/webp" hidden><button class="btn primary btn-sm" type="submit">Upload photo</button></form><small class="muted">JPG, PNG or WebP, up to 5 MB.</small></div></div><form id="profile-form"><div class="form-grid"><div class="field"><label>Full name</label><input name="name" required minlength="2" value="${esc(u.name)}"></div><div class="field"><label>Email</label><input name="email" type="email" required value="${esc(u.email)}"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(u.phone||"")}"></div>${donor?`<div class="field"><label>Broad location</label><input name="location" value="${esc(p.location||"")}"></div><div class="field"><label>Preferred language</label><select name="language">${["English","Hausa","Yoruba","Igbo"].map(x=>`<option ${p.language===x?"selected":""}>${x}</option>`).join("")}</select></div><div class="field"><label>Blood group (self-reported)</label><select name="blood_group">${["Not provided","A+","A-","B+","B-","AB+","AB-","O+","O-"].map(x=>`<option ${p.blood_group===x?"selected":""}>${x}</option>`).join("")}</select></div>`:""}${facility?`<div class="field"><label>Facility name</label><input name="facility_name" value="${esc(f.name||"")}"></div><div class="field"><label>Facility address</label><input name="facility_address" value="${esc(f.address||"")}"></div><div class="field"><label>Facility contact</label><input name="facility_contact" value="${esc(f.contact||"")}"></div>`:""}</div><details class="password-change"><summary>Change password</summary><div class="form-grid"><div class="field"><label>Current password</label><input name="current_password" type="password" autocomplete="current-password"></div><div class="field"><label>New password</label><input name="new_password" type="password" minlength="8" autocomplete="new-password"></div></div></details><button class="btn primary" type="submit">Save changes</button></form><div class="notice warn" style="margin-top:18px">This is a synthetic demonstration environment.</div></div>`}
async function saveProfile(event){event.preventDefault();const form=event.target;if(!form.reportValidity())return;const button=form.querySelector('[type="submit"]'),previous=setButtonLoading(button,"Saving..."),data=Object.fromEntries(new FormData(form));if(!data.new_password){delete data.new_password;delete data.current_password}try{await api("/api/me/profile",{method:"PATCH",body:JSON.stringify(data)});state.user=await api("/api/me");localStorage.setItem("lc_user",JSON.stringify(state.user));toast("Profile updated","success");await renderApp()}catch(error){toast(error.message,"error");restoreButton(button,previous)}}
async function uploadAvatar(event){event.preventDefault();const input=document.getElementById("profile-image"),file=input.files[0];if(!file){toast("Choose an image first.","error");return}const button=event.target.querySelector('[type="submit"]'),previous=setButtonLoading(button,"Uploading..."),data=new FormData();data.append("file",file);try{await apiUpload("/api/me/avatar",data);state.user=await api("/api/me");localStorage.setItem("lc_user",JSON.stringify(state.user));toast("Profile photo updated","success");await renderApp()}catch(error){toast(error.message,"error");restoreButton(button,previous)}}
async function editUser(id){try{const users=await api("/api/admin/users"),u=users.find(x=>x.id===id);if(!u)return;const p=u.profile||{},f=u.facility||{};showModal("Edit user account",`<form id="admin-user-form" data-user-id="${id}"><div class="form-grid"><div class="field"><label>Name</label><input name="name" required value="${esc(u.name)}"></div><div class="field"><label>Email</label><input name="email" type="email" required value="${esc(u.email)}"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(u.phone||"")}"></div><div class="field"><label>Role</label><select name="role">${[["donor","Donor"],["facility","Facility"],["admin","Administrator"]].map(([v,l])=>`<option value="${v}" ${u.role===v?"selected":""}>${l}</option>`).join("")}</select></div><div class="field"><label>Location</label><input name="location" value="${esc(p.location||f.address||"")}"></div><div class="field"><label>Language</label><input name="language" value="${esc(p.language||"English")}"></div><div class="field"><label>Self-reported blood group</label><select name="blood_group">${["Not provided","A+","A-","B+","B-","AB+","AB-","O+","O-"].map(x=>`<option ${p.blood_group===x?"selected":""}>${x}</option>`).join("")}</select></div><div class="field"><label>Availability</label><select name="availability">${["available","temporarily unavailable","paused"].map(x=>`<option ${p.availability===x?"selected":""}>${x}</option>`).join("")}</select></div><div class="field"><label>Outreach radius (km)</label><input name="radius_km" type="number" min="1" max="250" value="${p.radius_km||25}"></div><label class="checkline"><input type="checkbox" name="consent" ${p.consent?"checked":""}><span>Invitation consent</span></label><label class="checkline"><input type="checkbox" name="email_enabled" ${p.email_enabled?"checked":""}><span>Email alerts</span></label><label class="checkline"><input type="checkbox" name="sms_enabled" ${p.sms_enabled?"checked":""}><span>SMS alerts</span></label><label class="checkline"><input type="checkbox" name="inapp_enabled" ${p.inapp_enabled?"checked":""}><span>In-app alerts</span></label><div class="field"><label>Facility name</label><input name="facility_name" value="${esc(f.name||"")}"></div><div class="field"><label>Facility type</label><input name="facility_type" value="${esc(f.type||"Hospital")}"></div><div class="field"><label>Facility address</label><input name="facility_address" value="${esc(f.address||"")}"></div><div class="field"><label>Facility contact</label><input name="facility_contact" value="${esc(f.contact||"")}"></div><div class="field"><label>Facility verification</label><select name="facility_verification">${["pending","approved","rejected","suspended"].map(x=>`<option ${f.verification===x?"selected":""}>${x}</option>`).join("")}</select></div><div class="field full"><label>Set a new password <span class="muted">(leave blank to keep current)</span></label><input name="password" type="password" minlength="8" autocomplete="new-password"></div></div></form>`,`<button class="btn outline" data-close>Cancel</button><button class="btn primary" onclick="saveAdminUser()">Save user</button>`)}catch(error){toast(error.message,"error")}}
async function saveAdminUser(){const form=document.getElementById("admin-user-form");if(!form.reportValidity())return;const button=modalRoot.querySelector(".modal-foot .btn.primary"),previous=setButtonLoading(button,"Saving..."),data=Object.fromEntries(new FormData(form));for(const key of ["consent","email_enabled","sms_enabled","inapp_enabled"])data[key]=new FormData(form).has(key);data.radius_km=Number(data.radius_km||25);if(!data.password)data.password=null;try{await api(`/api/admin/users/${form.dataset.userId}`,{method:"PUT",body:JSON.stringify(data)});closeModal();toast("User account updated","success");go("users")}catch(error){toast(error.message,"error");restoreButton(button,previous)}}
async function reportsPage(){const d=await api("/api/reports");const entries=Object.entries(d.by_status);return head("Reports & analytics","Operational metrics for request coordination. Figures are synthetic demo data.")+statCards([{label:"Total requests",value:d.total_requests,icon:"requests"},{label:"Invitations",value:d.total_invitations,icon:"invitations"},{label:"Recorded responses",value:d.responses,icon:"users"},{label:"Demo delivery rate",value:d.delivery_rate+"%",icon:"notifications"}])+`<div class="panel"><div class="panel-head"><h3>Request lifecycle distribution</h3><span class="small muted">Current request counts</span></div><div class="chart-bars">${entries.map(([k,v])=>`<div class="bar-col"><b>${v}</b><div class="bar" style="height:${Math.max(8,v/Math.max(1,d.total_requests)*130)}px"></div><span>${esc(k)}</span></div>`).join("")||'<div class="empty">No data yet.</div>'}</div></div>`}
async function verificationPage(){const fs=await api("/api/admin/facilities");return head("Facility verification","Review institutional evidence and approve, reject or suspend facilities.")+`<div class="panel"><div class="toolbar"><input class="search" id="fac-search" placeholder="Search facilities…" oninput="filterTable('fac-search','fac-table')"></div><div class="table-wrap" id="fac-table"><table><thead><tr><th>Facility</th><th>Type</th><th>Address</th><th>Verification</th><th>Action</th></tr></thead><tbody>${fs.map(f=>`<tr data-search="${esc((f.name+f.address).toLowerCase())}"><td><b>${esc(f.name)}</b></td><td>${esc(f.type)}</td><td>${esc(f.address)}</td><td>${status(f.verification)}</td><td><button class="btn outline btn-sm" onclick="facilityReview(${f.id},'${esc(f.name)}')">Review</button></td></tr>`).join("")}</tbody></table></div></div><div class="notice warn">Demo seed facility is synthetic and not an actual verified hospital. Never represent demo approval as real-world accreditation.</div>`}
async function facilityReview(id,name){showModal("Review facility",`<h3>${esc(name)}</h3><p>Confirm evidence and identity checks outside this demo before changing verification status.</p><div class="notice warn">Approving a facility enables its staff to activate donor outreach. Only approve institutions after an authorised verification process.</div>`,`<button class="btn danger" onclick="setVerification(${id},'rejected')">Reject</button><button class="btn outline" onclick="setVerification(${id},'suspended')">Suspend</button><button class="btn teal" onclick="setVerification(${id},'approved')">Approve facility</button>`)}
async function setVerification(id,status){if(!confirm(`Set facility status to ${status}?`))return;try{await api(`/api/admin/facilities/${id}/verification`,{method:"PATCH",body:JSON.stringify({status})});closeModal();toast("Facility status updated");go("verification")}catch(e){toast(e.message,"error")}}
async function usersPage(){const us=await api("/api/admin/users");return head("User management","Review accounts and edit user details, roles, profile photos and passwords.")+`<div class="panel"><div class="toolbar"><input class="search" id="user-search" placeholder="Search users?" oninput="filterTable('user-search','user-table')"></div><div class="table-wrap" id="user-table"><table><thead><tr><th>User</th><th>Email</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody>${us.map(u=>`<tr data-search="${esc((u.name+u.email+u.role).toLowerCase())}"><td><div class="user-cell">${avatarMarkup(u,"user-avatar")}<b>${esc(u.name)}</b></div></td><td>${esc(u.email)}</td><td>${esc(u.role)}</td><td>${status(u.status)}</td><td><div class="user-actions"><button class="btn teal btn-sm" onclick="editUser(${u.id})">Edit</button><button class="btn outline btn-sm" onclick="toggleUser(${u.id},'${u.status==="active"?"suspended":"active"}')">${u.status==="active"?"Suspend":"Reactivate"}</button></div></td></tr>`).join("")}</tbody></table></div></div>`}
async function toggleUser(id,status){if(!confirm(`Change this account to ${status}?`))return;try{await api(`/api/admin/users/${id}/status`,{method:"PATCH",body:JSON.stringify({status})});toast("Account updated");go("users")}catch(e){toast(e.message,"error")}}
async function plansPage(){const ps=await api("/api/plans");return head("Plans & billing","Institution subscriptions fund advanced coordination; donor participation remains free.")+`<div class="grid3">${ps.map(p=>`<div class="plan-card"><div class="eyebrow">Institution plan</div><h3 style="margin-top:10px">${esc(p.name)}</h3><h2>${esc(p.price)}</h2><p>${p.seats} staff seats · ${p.requests} requests / month</p><p>${esc(p.features)}</p><button class="btn outline full" onclick="showInfo('Plan information','Plan limits and pricing are configurable. Validate prices with Nigerian pilot institutions before launch. Payment live mode is not enabled in this MVP.')">View details</button></div>`).join("")}</div><div class="notice" style="margin-top:18px">Payment processing is not connected in this demo. Never store raw card details. Subscription status must not affect clinical priority or emergency access.</div>`}
async function auditPage(){const rows=await api("/api/admin/audit");return head("Audit & security logs","Trace important actions across platform workflows.")+`<div class="panel"><div class="table-wrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Entity</th><th>Reference</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${new Date(r.time).toLocaleString()}</td><td>${esc(r.actor)}</td><td>${esc(r.action)}</td><td>${esc(r.entity)}</td><td>${esc(r.entity_id)}</td></tr>`).join("")}</tbody></table></div></div>`}
async function outreachPage(){const rs=await api("/api/requests");return head("Donor outreach","Review opt-in donor suggestions and approve invitations as a deliberate staff action.")+`<div class="notice warn" style="margin-bottom:16px">Outreach is available only to approved facilities. Suggestions use stated availability and consent preferences—not blood compatibility or medical eligibility.</div><div class="panel">${rs.map(r=>`<div class="profile-row"><div class="profile-icon">🩸</div><div style="flex:1"><b>${esc(r.reference)} · ${esc(r.blood_group)}</b><p class="small">${esc(r.location)} · ${status(r.status)}</p></div><button class="btn outline btn-sm" onclick="previewOutreach(${r.id})">Preview</button></div>`).join("")||'<div class="empty">Create a request to begin.</div>'}</div>`}
async function subscriptionPage(){return plansPage()}
async function staffPage(){const data=await api("/api/facility/staff");return head("Staff & roles","Review the staff accounts and membership roles assigned to your facility.")+(data.facility?`<div class="panel"><div class="panel-head"><div><h3>${esc(data.facility.name)}</h3><span class="small muted">${esc(data.facility.address)}</span></div>${status(data.facility.verification)}</div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Facility role</th><th>Membership</th><th>Account</th></tr></thead><tbody>${data.staff.map(member=>`<tr><td><b>${esc(member.name)}</b></td><td>${esc(member.email)}</td><td>${esc(member.role)}</td><td>${status(member.membership_status)}</td><td>${status(member.account_status)}</td></tr>`).join("")||'<tr><td colspan="5">No staff members are assigned to this facility yet.</td></tr>'}</tbody></table></div></div>`:'<div class="panel empty">No facility is linked to this account yet. Complete facility registration before reviewing staff access.</div>')+`<div class="notice">Facility records are restricted to active memberships. Staff invitations and role changes are not enabled in this demo; do not share passwords or create real staff accounts through this screen.</div>`}
async function privacyPage(){return head("Privacy & settings","Your consent, preferences and personal data controls.")+`<div class="panel" style="max-width:760px"><h3>Donor control</h3><p>You can pause invitations, update channel preferences or withdraw consent from Availability. Essential account/security notices may still be sent where permitted.</p><h3 style="margin-top:22px">Data minimisation</h3><p>LifeConnect should store only minimum necessary operational details. Do not include patient names or unrestricted medical notes in requests.</p><h3 style="margin-top:22px">Account deletion request</h3><p>For this MVP, contact platform support to request account deletion. A production release must implement verified access, correction, deletion and retention workflows.</p><button class="btn outline" onclick="showInfo('Privacy request','Contact platform support to initiate an account access, correction or deletion request. This demo does not process legal data-subject requests automatically.')">Request privacy assistance</button></div>`}
async function aiPage(){return head("LifeConnect AI assistant","Draft operational requests and get help with platform workflows. All outputs need human review.")+`<div class="two-col ai-workspace"><section class="panel"><div class="panel-head"><h3>Smart request drafting</h3><span class="status">Review required</span></div><p>Describe a request using facility-approved details. The assistant can organise a blood group, quantity and urgency into a draft.</p><div class="field"><label for="ai-request-prompt">Short operational summary</label><textarea id="ai-request-prompt" placeholder="Example: We need 4 units of O+ in Jos. Urgent request for the facility team."></textarea></div><button class="btn primary" onclick="generateAIDraft()">Generate draft</button><div id="ai-draft-output" aria-live="polite"></div></section><section class="panel"><div class="panel-head"><h3>Ask the help assistant</h3><span class="status approved">Available</span></div><p>Ask about invitations, facility verification, request statuses or account workflows.</p><div class="field"><label for="ai-help-question">Your question</label><textarea id="ai-help-question" placeholder="How does facility verification work?"></textarea></div><button class="btn outline" onclick="askAIHelp()">Ask assistant</button><div id="ai-help-output" aria-live="polite"></div></section></div><div class="notice warn">Product help can use OpenAI when configured and has built-in guidance when it is not. Request drafting uses structured extraction. Verify every draft. It must not decide compatibility, eligibility, diagnosis, treatment or transfusion care. Never enter patient names or sensitive health details.</div>`}
async function settingsPage(){return head("AI configuration","Review the bounded administrative AI capabilities and safety notices.")+`<div class="panel"><h3>Enabled demo capabilities</h3><div class="profile-row"><div class="profile-icon">✦</div><div><b>Smart request drafting</b><p class="small">Local deterministic fallback; staff must verify and edit all fields.</p></div>${status("fallback")}</div><div class="profile-row"><div class="profile-icon">文</div><div><b>Multilingual message drafting</b><p class="small">Placeholder unless a reviewed translation provider is connected.</p></div>${status("review required")}</div><div class="profile-row"><div class="profile-icon">?</div><div><b>Help assistant</b><p class="small">Approved product guidance; refuses clinical advice.</p></div>${status("active")}</div><div class="notice warn">AI must never determine blood compatibility, donor eligibility, diagnosis, treatment or transfusion advice. Keep personal and health data out of prompts unless strictly necessary, authorised and protected.</div></div>`}
async function generateAIDraft(){
  const button=document.querySelector("#ai-draft-output")?.previousElementSibling,previous=setButtonLoading(button,"Preparing draft...");
  const prompt=document.getElementById("ai-request-prompt").value.trim();
  if(!prompt){restoreButton(button,previous);toast("Enter a short operational summary first.","error");return}
  const output=document.getElementById("ai-draft-output");
  output.innerHTML='<div class="empty">Preparing a draft…</div>';
  try{
    const result=await api("/api/ai/request-draft",{method:"POST",body:JSON.stringify({text:prompt})});
    state.aiDraft=result.draft;
    output.innerHTML=`<div class="ai-result"><b>${esc(result.label)}</b><dl><div><dt>Blood group</dt><dd>${esc(result.draft.blood_group)}</dd></div><div><dt>Quantity</dt><dd>${esc(result.draft.quantity)}</dd></div><div><dt>Urgency</dt><dd>${esc(result.draft.urgency)}</dd></div></dl><p class="small">${esc(result.notice)}</p><button class="btn teal btn-sm" onclick="newRequest(state.aiDraft)">Review and edit draft</button></div>`;
  }catch(error){output.innerHTML="";toast(error.message,"error")}finally{restoreButton(button,previous)}
}
async function askAIHelp(){
  const button=document.querySelector("#ai-help-output")?.previousElementSibling,previous=setButtonLoading(button,"Checking...");
  const question=document.getElementById("ai-help-question").value.trim();
  if(!question){restoreButton(button,previous);toast("Enter a question first.","error");return}
  const output=document.getElementById("ai-help-output");
  output.innerHTML='<div class="empty">Checking approved guidance…</div>';
  try{
    const result=await api("/api/ai/help",{method:"POST",body:JSON.stringify({question})});
    output.innerHTML=`<div class="ai-result"><b>${esc(result.label)}</b><p>${esc(result.answer)}</p></div>`;
  }catch(error){output.innerHTML="";toast(error.message,"error")}finally{restoreButton(button,previous)}
}
async function helpPage(){return head("Help & support","Get answers about using LifeConnect AI.")+`<div class="two-col"><div class="panel"><h3>Ask the LifeConnect help assistant</h3><p>Ask about account workflows, invitations, facility verification or request statuses.</p><div class="field"><textarea id="help-question" placeholder="How does facility verification work?"></textarea></div><button class="btn primary" onclick="askHelp()">Ask assistant</button><div id="help-answer"></div></div><div class="panel"><h3>Frequently asked questions</h3>${[["Is blood sold on LifeConnect?","No. LifeConnect is not a blood marketplace and does not sell blood."],["Does accepting an invitation mean I am eligible?","No. It means you are willing to be contacted. The facility manages screening."],["Can AI determine compatibility?","No. Compatibility and eligibility decisions remain with qualified professionals."],["Is this an emergency service?","No. Follow your facility's approved emergency channels."]].map(([q,a])=>`<details style="padding:13px 0;border-bottom:1px solid var(--line)"><summary style="font-weight:700;font-size:13px;cursor:pointer">${q}</summary><p class="small">${a}</p></details>`).join("")}</div></div>`}
async function askHelp(){const q=document.getElementById("help-question").value;if(!q.trim())return;try{const d=await api("/api/ai/help",{method:"POST",body:JSON.stringify({question:q})});document.getElementById("help-answer").innerHTML=`<div class="notice" style="margin-top:15px"><b>${esc(d.label)}</b><p>${esc(d.answer)}</p></div>`}catch(e){toast(e.message,"error")}}
const pages={overview,requests:requestsPage,ai:aiPage,invitations:invitationsPage,availability:availabilityPage,notifications:notificationsPage,profile:profilePage,reports:reportsPage,verification:verificationPage,users:usersPage,plans:plansPage,subscription:subscriptionPage,audit:auditPage,outreach:outreachPage,staff:staffPage,privacy:privacyPage,settings:settingsPage,help:helpPage};
document.addEventListener("submit",e=>{if(e.target.id==="prefs")savePrefs(e);else if(e.target.id==="announcement-form")sendAnnouncement(e);else if(e.target.id==="profile-form")saveProfile(e);else if(e.target.id==="avatar-form")uploadAvatar(e)});
(async()=>{if(state.token){try{await renderApp();return}catch{}}publicSite()})();

