function homeShowcase(){return `<section class="section showcase-section" id="dashboard-preview"><div class="section-head"><div class="eyebrow">Inside the workspace</div><h2>A clearer view of the coordination journey</h2><p>Explore how teams follow requests, donor choices and next steps.</p></div><div class="dashboard-preview" role="img" aria-label="Illustrative facility dashboard preview with fictional sample statistics"><div class="preview-topbar"><div><img class="preview-brand-logo" src="/static/lifeconnect-logo-small.png" alt="LifeConnect AI"><b>Workspace preview</b></div><span class="preview-demo-label">ILLUSTRATIVE DEMO DATA</span></div><div class="preview-layout"><aside class="preview-sidebar"><b>Facility overview</b><span>Requests</span><span>Donor outreach</span><span>Reports</span></aside><div class="preview-main"><div class="preview-heading"><div><span>FACILITY DASHBOARD</span><h3>Coordination overview</h3></div><span class="preview-status">Demo workspace</span></div><div class="preview-stats"><div><span>Donor profiles</span><b>2,480</b><small>Synthetic sample</small></div><div><span>Facilities</span><b>36</b><small>Illustrative only</small></div><div><span>Open requests</span><b>124</b><small>Sample records</small></div><div><span>Responses</span><b>78%</b><small>Example metric</small></div></div><div class="preview-panels"><div class="preview-chart"><div class="preview-panel-title"><b>Request activity</b><span>Example view</span></div><div class="chart-bars" aria-hidden="true"><i style="height:34%"></i><i style="height:49%"></i><i style="height:42%"></i><i style="height:72%"></i><i style="height:58%"></i><i style="height:88%"></i><i style="height:68%"></i></div><div class="chart-labels"><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span><span>Sun</span></div></div><div class="preview-activity"><div class="preview-panel-title"><b>Recent activity</b><span>Sample</span></div><p><i class="activity-bullet teal-bullet"></i><span><b>Request reviewed</b><small>Facility workflow</small></span></p><p><i class="activity-bullet red-bullet"></i><span><b>Donor response received</b><small>Volunteer choice</small></span></p><p><i class="activity-bullet blue-bullet"></i><span><b>Outreach batch approved</b><small>Human review</small></span></p></div></div></div></div></div><p class="preview-disclaimer">All figures are fictional sample data.</p></section><section class="section ai-showcase" id="ai-preview"><div class="ai-showcase-copy"><div class="eyebrow">A helpful assistant, with limits</div><h2>Make routine admin work easier to review.</h2><p>Facility staff can turn a short operational note into an editable request draft and get answers about platform workflows.</p><ul><li>Suggests a structured request draft</li><li>Keeps human review and edits in control</li><li>Does not make clinical or donor-eligibility decisions</li></ul><button class="btn teal" onclick="openFacilityDemo()">Try the facility demo</button><p class="small">Demo login: staff@lifeconnect.demo / Password: Demo123!</p></div><div class="ai-preview-card"><div class="ai-preview-header"><span class="ai-spark">&#10022;</span><div><b>LifeConnect assistant</b><small>Product help</small></div><span class="preview-status">Review required</span></div><div class="ai-chat-bubble">"Please prepare a request for 4 units of O+ in Jos."</div><div class="ai-response"><b>Suggested draft fields</b><div><span>Blood group</span><strong>O+</strong></div><div><span>Quantity</span><strong>4 units</strong></div><div><span>Urgency</span><strong>Standard</strong></div><small>Example only. Staff must verify and edit.</small></div></div></section><section class="section image-gallery"><div class="section-head"><div class="eyebrow">People make the difference</div><h2>Donors, care teams and stronger communities</h2><p>LifeConnect brings volunteer donors and healthcare teams together around clear, human-led coordination.</p></div><div class="gallery-grid"><figure><img src="/static/lifeconnect-hero.svg" alt="A volunteer donor meeting a healthcare worker outside a community clinic"><figcaption><b>One donor, one caring community</b><span>Participation stays voluntary and donor-controlled.</span></figcaption></figure><figure><img src="/static/donor-community.svg" alt="A diverse group of adult volunteer blood donors at a community event"><figcaption><b>Community of volunteer donors</b><span>Every person chooses whether and how to take part.</span></figcaption></figure><figure><img src="/static/care-team.svg" alt="Healthcare workers reviewing a donor coordination dashboard together"><figcaption><b>Healthcare teams in control</b><span>Staff coordinate requests and make every operational decision.</span></figcaption></figure></div></section>`}
function openFacilityDemo(){authPage("login","facility");document.getElementById("auth-email").value="staff@lifeconnect.demo";document.getElementById("auth-password").value="Demo123!"}
function whyMattersSection(){return `<section class="section why-matters" aria-roledescription="carousel" aria-label="Why blood donation coordination matters"><div class="why-heading"><div><div class="eyebrow">Why it matters</div><h2>Small acts of coordination can make a real difference.</h2></div><div class="why-controls"><button class="btn outline btn-sm" type="button" onclick="moveWhySlide(-1)" aria-label="Previous slide">&#8592;</button><button class="btn outline btn-sm" type="button" onclick="toggleWhyPause()" id="why-pause">Pause</button><button class="btn outline btn-sm" type="button" onclick="moveWhySlide(1)" aria-label="Next slide">&#8594;</button></div></div><div class="why-track" id="why-track" aria-live="polite"><article class="why-slide active"><span class="why-number">01</span><div><h3>Every donor stays in control.</h3><p>Clear consent and notification preferences help volunteers choose if and when they want to hear from a participating facility.</p></div><span class="why-icon" aria-hidden="true">&#9825;</span></article><article class="why-slide"><span class="why-number">02</span><div><h3>Requests reach people who opted in.</h3><p>Verified facilities can contact active donors through their selected channels, with request details and a clear way to respond.</p></div><span class="why-icon" aria-hidden="true">&#8599;</span></article><article class="why-slide"><span class="why-number">03</span><div><h3>Teams get a clearer follow-up path.</h3><p>Shared request status and donor responses help authorised staff coordinate next steps while clinical decisions remain with professionals.</p></div><span class="why-icon" aria-hidden="true">&#10010;</span></article></div><div class="why-dots" role="group" aria-label="Choose a slide"><button class="active" aria-label="Slide 1" onclick="showWhySlide(0)"></button><button aria-label="Slide 2" onclick="showWhySlide(1)"></button><button aria-label="Slide 3" onclick="showWhySlide(2)"></button></div></section>`}
let whyTimer=null,whyIndex=0,whyPaused=false;
function showWhySlide(index){const slides=[...document.querySelectorAll(".why-slide")],dots=[...document.querySelectorAll(".why-dots button")];if(!slides.length)return;whyIndex=(index+slides.length)%slides.length;slides.forEach((slide,i)=>slide.classList.toggle("active",i===whyIndex));dots.forEach((dot,i)=>{dot.classList.toggle("active",i===whyIndex);dot.setAttribute("aria-current",i===whyIndex?"true":"false")})}
function moveWhySlide(direction){showWhySlide(whyIndex+direction)}
function toggleWhyPause(){whyPaused=!whyPaused;const button=document.getElementById("why-pause");if(button)button.textContent=whyPaused?"Play":"Pause"}
function startWhyCarousel(){clearInterval(whyTimer);whyIndex=0;whyPaused=window.matchMedia("(prefers-reduced-motion: reduce)").matches;showWhySlide(0);const pause=document.getElementById("why-pause");if(pause)pause.textContent=whyPaused?"Play":"Pause";whyTimer=setInterval(()=>{if(!whyPaused)moveWhySlide(1)},6500)}
async function publicPage(page="home"){
  const nav=[["home","Home"],["about","About & safety"],["facilities","Find a facility"],["hospitals","For hospitals"],["help","Help"]];
  const navHtml=nav.map(([key,label])=>`<button ${page===key?'aria-current="page"':""} onclick="publicPage('${key}')">${label}</button>`).join("");
  const footerLinks=[["about","About & safety"],["facilities","Find a facility"],["hospitals","For hospitals"],["help","Help centre"],["privacy","Privacy"],["terms","Terms"]];
  const footerHtml=footerLinks.map(([key,label])=>`<p><button class="footer-link" onclick="publicPage('${key}')">${label}</button></p>`).join("");
  const header=`<header class="topbar"><button class="brand brand-button" onclick="publicPage('home')" aria-label="LifeConnect AI home"><img class="brand-logo" src="/static/lifeconnect-logo-small.png" alt="LifeConnect AI"></button><button class="btn outline btn-sm mobile-nav-toggle" onclick="togglePublicNav()" aria-label="Toggle navigation">☰ Menu</button><nav class="navlinks" id="public-nav">${navHtml}</nav><div class="nav-actions"><button class="btn ghost" onclick="authPage('login')">Sign in</button><button class="btn primary" onclick="authPage('register')">Join as donor</button></div></header>`;
  const footer=`<footer class="footer"><div><div class="brand"><img class="brand-logo" src="/static/lifeconnect-logo-small.png" alt="LifeConnect AI"></div><p>Connecting volunteer donors with verified institutions through responsible coordination.</p><p>© 2026 LifeConnect AI · Nigeria-first MVP</p></div><div><h4>Explore</h4>${footerHtml}</div><div><h4>Get started</h4><p><button class="footer-link" onclick="authPage('register')">Become a donor</button></p><p><button class="footer-link" onclick="authPage('register','facility')">Register a facility</button></p><p><button class="footer-link" onclick="showInfo('Emergency support','LifeConnect is not an emergency service. Contact your facility using its approved emergency channels.')">Emergency disclaimer</button></p></div></footer>`;
  let content="";
  if(page==="home"){
    content=`<section class="hero"><div><div class="eyebrow">A more connected donor community</div><h1>When every moment matters, <em>connection</em> matters.</h1><p>LifeConnect AI helps verified hospitals and blood banks coordinate volunteer donor outreach with clear workflows, donor-controlled communication and practical operational insights.</p><div class="hero-actions"><button class="btn teal" onclick="authPage('register')">Become a volunteer donor →</button><button class="btn outline" onclick="authPage('register','facility')">For hospitals</button></div><p class="small">Free donor participation · Facility verification · Human-led clinical decisions</p></div><div class="hero-art"><img class="hero-image" src="/static/lifeconnect-hero.svg" alt="Illustration of a volunteer donor and healthcare worker beside a community clinic"><div class="float-card one">✓ Verified-facility workflow</div><div class="float-card two">♡ Volunteer-first coordination</div></div></section><section class="section" id="how"><div class="section-head"><div class="eyebrow">One coordinated workflow</div><h2>Designed around trust, clarity and action</h2><p>Bring donor preferences, facility requests and operational follow-through into one coordination experience.</p></div><div class="grid3"><article class="feature"><div class="feature-icon">♙</div><h3>Donor-controlled participation</h3><p>Volunteers manage availability, language, location preferences, consent and notification channels.</p></article><article class="feature"><div class="feature-icon">▣</div><h3>Facility-led requests</h3><p>Authorised staff create requests, review outreach suggestions and explicitly approve invitation batches.</p></article><article class="feature"><div class="feature-icon">✦</div><h3>AI-assisted administration</h3><p>Support request drafting, message preparation and language workflows—with human review.</p></article></div></section><section class="safety-strip"><div aria-hidden="true" style="font-size:28px">ⓘ</div><div><b>Important safety boundary</b><p>LifeConnect coordinates communication only. It does not sell blood or replace screening, testing, clinical judgement, transfusion services or emergency care.</p><button class="btn outline btn-sm" onclick="publicPage('about')">Read about safety</button></div></section>`;
  }else if(page==="facilities"){
    content=`<section class="public-page"><div class="public-page-inner"><div class="eyebrow">Verified institutions</div><h1>Find a participating facility</h1><p class="lead">Browse facilities that have completed platform verification. Contact details and locations are provided by each institution.</p><div id="facility-directory" class="grid3"><div class="panel">Loading verified facilities…</div></div><div class="notice warn" style="margin-top:20px">This directory is not an emergency service. If you need urgent care, contact local emergency services or a healthcare facility directly.</div></div></section>`;
  }else if(page==="about"){
    content=`<section class="public-page"><div class="public-page-inner"><div class="eyebrow">About LifeConnect AI</div><h1>Responsible coordination, with people in control.</h1><p class="lead">LifeConnect helps verified hospitals and blood banks coordinate communication with volunteer donors. It is not a blood marketplace and does not sell blood.</p><div class="grid3"><article class="feature"><div class="feature-icon">✓</div><h3>Facility-led</h3><p>Institutions and authorised staff own request review and every real-world decision.</p></article><article class="feature"><div class="feature-icon">♡</div><h3>Volunteer-first</h3><p>Donors control consent, availability, preferred language and communication choices.</p></article><article class="feature"><div class="feature-icon">ⓘ</div><h3>Safety boundary</h3><p>The platform does not determine compatibility, donor eligibility, diagnosis, treatment or transfusion decisions.</p></article></div><div class="notice warn" style="margin-top:22px">Never use this website as an emergency channel. Donation acceptance only means willingness to be contacted; the facility manages screening and clinical decisions.</div></div></section>`;
  }else if(page==="hospitals"){
    content=`<section class="public-page"><div class="public-page-inner"><div class="eyebrow">For hospitals and blood banks</div><h1>Coordinate outreach with a clear human review step.</h1><p class="lead">Create requests, review donor responses and maintain operational visibility. Public outreach is disabled until a facility is verified.</p><div class="grid3"><article class="feature"><h3>Structured requests</h3><p>Track request status, location, urgency labels and expiry using facility-entered information.</p></article><article class="feature"><h3>Reviewed outreach</h3><p>See preference-based suggestions and approve each demo invitation batch deliberately.</p></article><article class="feature"><h3>Operational visibility</h3><p>Review request history, notifications, response activity and audit records.</p></article></div><div class="hero-actions"><button class="btn primary" onclick="authPage('register','facility')">Register your facility</button><button class="btn outline" onclick="publicPage('facilities')">View verified facilities</button></div><div class="notice" style="margin-top:22px">Facility approval and staff workflows must be reviewed by your institution before any real-world use. Demo records are synthetic.</div></div></section>`;
  }else if(page==="help"){
    content=`<section class="public-page"><div class="public-page-inner"><div class="eyebrow">Help & support</div><h1>How can we help?</h1><p class="lead">Find answers about accounts, donor invitations and participating facilities.</p><div class="panel">${[["Is this an emergency service?","No. Use your facility's approved emergency channels or contact local emergency services."],["Does accepting an invitation mean I am medically eligible?","No. It means only that you are willing to be contacted. The facility manages screening."],["Can LifeConnect sell blood or decide compatibility?","No. LifeConnect coordinates communication and does not sell blood or make clinical decisions."],["How are facilities verified?","Facility accounts remain pending until reviewed by the platform verification team; public outreach is blocked until approval."]].map(([q,a])=>`<details class="faq-item"><summary>${q}</summary><p>${a}</p></details>`).join("")}</div></div></section>`;
  }else if(page==="privacy"){
    content=`<section class="public-page"><div class="public-page-inner"><div class="eyebrow">Privacy</div><h1>Privacy notice</h1><p class="lead">This demonstration uses synthetic records. Do not enter real donor or patient information.</p><div class="panel"><h3>Data and choices</h3><p>Donor participation is voluntary. Registered donors can update preferences, pause invitations and withdraw invitation consent from their account.</p><h3>Minimum necessary information</h3><p>Do not include patient names or unrestricted medical details in request notes. A production service requires approved retention, deletion, access and incident-response procedures.</p><h3>Demo limitations</h3><p>This MVP does not provide legal data-subject request processing or production security guarantees. Obtain appropriate Nigerian privacy, legal and clinical review before any pilot.</p></div></div></section>`;
  }else{
    content=`<section class="public-page"><div class="public-page-inner"><div class="eyebrow">Terms</div><h1>Terms of use</h1><div class="panel"><h3>Coordination only</h3><p>LifeConnect AI is a communication and workflow tool, not a blood marketplace, medical service or emergency service.</p><h3>Clinical responsibility</h3><p>Facilities and qualified healthcare professionals are responsible for donor screening, testing, compatibility decisions, collection, storage, release and transfusion.</p><h3>Demonstration environment</h3><p>This MVP is for demonstration with synthetic data only. Do not use it to coordinate real-world outreach or make clinical decisions.</p></div><div class="notice warn" style="margin-top:18px">These demo terms are informational and are not a substitute for approved legal terms.</div></div></section>`;
  }
  if(page==="home")content=content.replace('<section class="safety-strip">',homeShowcase()+whyMattersSection()+'<section class="section landing-chat-section"><div class="landing-chat-copy"><div class="eyebrow">LifeConnect AI assistant</div><h2>Questions about using LifeConnect?</h2><p>Ask about accounts, invitations, facility verification or platform workflows.</p><p class="small">The assistant cannot provide medical advice. Do not enter personal or patient details.</p></div><div class="landing-chat panel"><div id="landing-chat-log" class="landing-chat-log" aria-live="polite"><div class="chat-message assistant"><b>LifeConnect assistant</b><p>Hi! I can explain how the platform works. What would you like to know?</p></div></div><form id="landing-chat-form" class="landing-chat-form"><label class="sr-only" for="landing-chat-input">Your question</label><input id="landing-chat-input" name="question" maxlength="1000" placeholder="Ask a question…" required><button class="btn primary" type="submit">Send</button></form></div></section><section class="safety-strip">');
  app.innerHTML=header+content+footer;
  if(page==="home")startWhyCarousel();
  if(page==="home"){
    const chatForm=document.getElementById("landing-chat-form");
    chatForm?.addEventListener("submit",async event=>{
      event.preventDefault();
      const input=document.getElementById("landing-chat-input"), log=document.getElementById("landing-chat-log"), question=input.value.trim();
      if(!question)return;
      const history=state.chatHistory||(state.chatHistory=[]);
      history.push({role:"user",text:question});
      log.insertAdjacentHTML("beforeend",`<div class="chat-message user"><p>${esc(question)}</p></div><div class="chat-message assistant chat-thinking"><b>LifeConnect assistant</b><p>Thinking…</p></div>`);
      input.value="";input.disabled=true;chatForm.querySelector("button").disabled=true;log.scrollTop=log.scrollHeight;
      try{
        const prompt=history.slice(-6).map(message=>`${message.role==="user"?"Visitor":"Assistant"}: ${message.text}`).join("\n");
        const result=await api("/api/ai/chat",{method:"POST",body:JSON.stringify({question:prompt})});
        history.push({role:"assistant",text:result.answer});
        log.querySelector(".chat-thinking")?.remove();
        log.insertAdjacentHTML("beforeend",`<div class="chat-message assistant"><b>LifeConnect assistant</b><p>${esc(result.answer)}</p></div>`);
      }catch(error){
        log.querySelector(".chat-thinking")?.remove();
        log.insertAdjacentHTML("beforeend",`<div class="chat-message assistant"><p>${esc(error.message)}</p></div>`);
      }finally{input.disabled=false;chatForm.querySelector("button").disabled=false;input.focus();log.scrollTop=log.scrollHeight;}
    });
  }
  if(page==="facilities"){
    try{
      const facilities=await api("/api/facilities");
      const directory=document.getElementById("facility-directory");
      directory.innerHTML=facilities.length?facilities.map(f=>`<article class="feature facility-card"><div class="eyebrow">Verified facility</div><h3>${esc(f.name)}</h3><p>${esc(f.type)} · ${esc(f.address)}</p><p class="small">${esc(f.contact||"Contact information not provided")}</p></article>`).join(""):'<div class="panel empty">No verified facilities are listed yet. Please check back later.</div>';
    }catch(error){
      document.getElementById("facility-directory").innerHTML=`<div class="panel notice error">Unable to load the facility directory: ${esc(error.message)}</div>`;
    }
  }
  window.scrollTo({top:0,behavior:"smooth"});
}
function togglePublicNav(){document.getElementById("public-nav")?.classList.toggle("open")}
function authPage(mode,role="donor"){
  const isLogin=mode==="login", initialRole=role==="facility"?"facility":"donor";
  const registrationFields=isLogin?"":`<div class="field"><label for="auth-name" id="auth-name-label">${initialRole==="facility"?"Facility legal name":"Full name"}</label><input id="auth-name" name="name" autocomplete="name" minlength="2" maxlength="120" required></div>
    <div class="field"><label for="auth-phone">Phone number <span class="muted">(optional)</span></label><input id="auth-phone" name="phone" type="tel" autocomplete="tel"></div>
    <div class="field"><label for="auth-role">Account type</label><select id="auth-role" name="role"><option value="donor" ${initialRole==="donor"?"selected":""}>Volunteer donor</option><option value="facility" ${initialRole==="facility"?"selected":""}>Hospital or blood bank</option></select></div>
    <div class="field"><label for="auth-location" id="auth-location-label">${initialRole==="facility"?"Facility address":"Broad location"}</label><input id="auth-location" name="location" autocomplete="street-address" required></div>
    <div class="field" id="auth-language-field" ${initialRole==="facility"?"hidden":""}><label for="auth-language">Preferred language</label><select id="auth-language" name="language"><option>English</option><option>Hausa</option><option>Yoruba</option><option>Igbo</option></select></div>
    <label class="checkline" id="auth-terms-line"><input id="auth-terms" type="checkbox" required><span>I agree to the demo terms and understand this is not an emergency service.</span></label>
    <label class="checkline" id="auth-consent-line" ${initialRole==="facility"?"hidden":""}><input id="auth-consent" name="consent" type="checkbox"><span>I consent to receive donor invitations through my selected channels. I can withdraw consent or pause at any time.</span></label>`;
  app.innerHTML=`<div class="auth-wrap"><aside class="auth-side"><button class="brand brand-button" onclick="publicSite()" aria-label="LifeConnect AI home"><img class="brand-logo" src="/static/lifeconnect-logo-small.png" alt="LifeConnect AI"></button><div><div class="eyebrow" style="color:#9ce3d8">Trusted coordination</div><h1>Good things happen when people connect.</h1><p>One platform for donor-controlled participation and verified facility workflows.</p></div><p class="small">LifeConnect AI ? Blood donation coordination only</p></aside><main class="auth-main"><section class="auth-card"><button class="btn ghost btn-sm" type="button" onclick="publicSite()">? Back to website</button><div style="height:25px"></div><div class="eyebrow">${isLogin?"Welcome back":"Get started"}</div><h2>${isLogin?"Sign in to LifeConnect":"Create your account"}</h2><p>${isLogin?"Continue to your secure coordination workspace.":"Donor participation is free. Facility accounts require verification."}</p><form id="auth-form">${registrationFields}<div class="field"><label for="auth-email">Email address</label><input id="auth-email" name="email" type="email" autocomplete="email" required></div><div class="field"><label for="auth-password">Password</label><input id="auth-password" name="password" type="password" autocomplete="${isLogin?"current-password":"new-password"}" minlength="${isLogin?1:8}" required></div><button class="btn primary full" id="auth-submit" type="submit">${isLogin?"Sign in":"Create account"}</button></form><div class="auth-switch"><span>${isLogin?"New to LifeConnect?":"Already registered?"}</span><button class="btn ghost btn-sm" type="button" onclick="authPage('${isLogin?"register":"login"}','${initialRole}')">${isLogin?"Create an account":"Sign in instead"}</button></div>${isLogin?`<div class="notice" style="margin-top:16px"><b>Demo accounts</b><br>admin@lifeconnect.demo ? staff@lifeconnect.demo ? donor@lifeconnect.demo<br>Password: <b>Demo123!</b></div>`:""}</section></main></div>`;
  const form=document.getElementById("auth-form");
  if(!isLogin){
    document.getElementById("auth-role").addEventListener("change",event=>{
      const facility=event.target.value==="facility";
      document.getElementById("auth-name-label").textContent=facility?"Facility legal name":"Full name";
      document.getElementById("auth-location-label").textContent=facility?"Facility address":"Broad location";
      document.getElementById("auth-language-field").hidden=facility;
      document.getElementById("auth-consent-line").hidden=facility;
    });
  }
  form.addEventListener("submit",async event=>{
    event.preventDefault();
    if(!form.reportValidity())return;
    const values=Object.fromEntries(new FormData(form));
    const payload=isLogin?{email:values.email.trim(),password:values.password}:{...values,email:values.email.trim(),consent:document.getElementById("auth-consent").checked};
    const button=document.getElementById("auth-submit");
    const previous=setButtonLoading(button,isLogin?"Signing in?":"Creating account?");
    try{
      const data=await api(isLogin?"/api/auth/login":"/api/auth/register",{method:"POST",body:JSON.stringify(payload)});
      saveSession(data);state.page="overview";await renderApp();startNotificationPolling();toast(isLogin?"Welcome back.":"Your account has been created.","success");
    }catch(error){toast(error.message,"error");restoreButton(button,previous);}
  });
}
async function startNotificationPolling(){
  if(state.notificationTimer||!state.token)return;
  try{
    const initial=await api("/api/notifications");
    state.lastNotificationId=initial[0]?.id||0;refreshNotificationBadge(initial);
  }catch(error){
    toast(`Notifications could not be checked: ${error.message}`,"error");
    return;
  }
  state.notificationTimer=setInterval(async()=>{
    if(!state.token){clearInterval(state.notificationTimer);state.notificationTimer=null;return}
    try{
      const current=await api("/api/notifications");
      const latest=current[0];
      if(latest&&latest.id>state.lastNotificationId){
        state.lastNotificationId=latest.id;
        refreshNotificationBadge(current);
        toast(`${latest.title}: ${latest.message}`,"success");
      }
    }catch(error){
      clearInterval(state.notificationTimer);
      state.notificationTimer=null;
      toast(`Live notifications paused: ${error.message}`,"error");
    }
  },45000);
}
if(state.token)setTimeout(startNotificationPolling,1000);
